  'base-render.components-date-range-style-calendar.c001': "/* Calendar block: soft fill + hairline (with zero shadow that is what draws the boundary).",
  'base-render.components-date-range-style-calendar.c002': "   **Width cap {p0}px**: a month has its own natural width — in a 1000px cell",
  'base-render.components-date-range-style-calendar.c003': "   a day stretches to 170px with the number dangling alone in the middle, which does not read like a calendar (only seen on a real device at 1280).",
  'base-render.components-date-range-style-calendar.c004': "   Width beyond the cap stays outside the block (the other rows still fill), and the cell width stays around {p0}px. */",
  'base-render.components-date-range-style-calendar.c005': "/* Each day cell: hit box ≥44×44 (matrix gap 0px: gaps fold into the cells, see the `style.ts` header).",
  'base-render.components-date-range-style-calendar.c006': "   Four shapes: in-range = paper block, the two ends = **accent surface** (the day's number is written in the cell = it has text ⇒ soft fill `accent-soft`",
  'base-render.components-date-range-style-calendar.c007': "   + primary text `accent-text` + primary outline `accent`, see `docs/base/base-render/选中态与皮肤语言.md` section 3),",
  'base-render.components-date-range-style-calendar.c008': "   adjacent month = muted text, today = a hairline ring.",
  'base-render.components-date-range-style-calendar.c009': "   `is-adj` carries `:not(.is-end)`: an adjacent-month day **can** be one end of the range (`render.ts` judges the two things separately) —",
  'base-render.components-date-range-style-calendar.c010': "   if \"muted text\" overrode the selected surface's `accent-text` there, the selected text would drop back to `ink-3` (only 4.48:1 against soft fill on paper). */",
  'base-render.components-date-range-style-calendar.c011': "/* Narrow tier **full-bleed**: when this component's own inner width ≤{p0}px,",
  'base-render.components-date-range-style-calendar.c012': "   7 columns × 44px = 308px cannot even pay for \"the calendar's own left/right padding + the block's left/right padding\" (the 320 tier does not get this one,",
  'base-render.components-date-range-style-calendar.c013': "   each cell only 34.8px, effective hit 34–36px < the 44 floor). Fold both paddings into the cells: the calendar extends",
  'base-render.components-date-range-style-calendar.c014': "   {p0}px on each side (= the block's left/right padding, **the same constant**), its own left/right padding goes to zero",
  'base-render.components-date-range-style-calendar.c015': "   ⇒ at the 320 tier each cell is 45.1px (effective hit 44–46px).",
  'base-render.components-date-range-style-calendar.c016': "   The extension ≤ the block padding ⇒ the calendar always stays inside the block border, no horizontal overflow at any tier (all four tiers are measured).",
  'base-render.components-date-range-style-calendar.c017': "   The judge is **this component's own inner width** (container query), not the viewport width. */",
  /* ── packages/base-render/src/components/date-range/style.ts（#1226 迁入） ── */
  'base-render.components-date-range-style.c001': '/* date-range (date range · form B "calendar thumbnail"): start and end cells + a row of quick presets (the active one carries ✓) + one month of cells,',
  'base-render.components-date-range-style.c002': '   the method line underneath names "which preset is active, from which day to which day, how many days in total". With zero shadow, hierarchy comes from hairlines and fill blocks. */',
  'base-render.components-date-range-style.c003': "/* First row: name + status word (`Active: this week` / `Custom range` / `Not chosen yet` / `Updating`). */",
  'base-render.components-date-range-style.c004': '/* Status word: a hairline-bordered tag (the **word** tier: reskinning cannot take away "which preset is active"). */',
  'base-render.components-date-range-style.c005': "/* Start and end cells: two columns (stacked in narrow containers), {p0}px between them and the presets / calendar. */",
  'base-render.components-date-range-style.c006': "/* The preset row: the active one carries ✓ and takes the **accent surface** (soft fill `accent-soft` + primary text `accent-text`",
  'base-render.components-date-range-style.c007': "   + primary outline `accent`) + bold (**shape + weight + colour**, all three). The rule lives in",
  'base-render.components-date-range-style.c008': '   `docs/base/base-render/选中态与皮肤语言.md` section 3: a selected surface with text must not be written as "solid inverted". */',
  'base-render.components-date-range-style.c009': "/* The ✓ is always in the markup, only the pressed one shows — the runtime only flips `aria-pressed`, it never touches the mark. */",
  'base-render.components-date-range-style.c010': "/* Hover: wrapped in the device-capability query only (`hover:hover`), and **not the only path**.",
  'base-render.components-date-range-style.c011': "   The hint applies only to cells that are **not the two ends**: those two are the selected surface (soft fill + primary text + primary outline),",
  'base-render.components-date-range-style.c012': "   and if hover swapped the fill to `surface` and the outline to `ink-2`, the selected state would fall apart at the moment of hovering. */",
  'base-render.components-date-range-style.c013': "/* Real press: `transform` only (visible within 80ms). */",
  'base-render.components-date-range-style.c014': "/* Visible focus: month keys, presets, day cells and both end cells all get ≥2px outline. */",
  'base-render.components-date-range-style.c015': '/* Updating: readings and cells stay as they are (width locked), the status word switches to "Updating"; the cursor is `progress`. */',
  'base-render.components-date-range-style.c016': "/* Disabled: an unexplained non-editable middle tier is not allowed (rendering already requires `disabledReason`). */",
  'base-render.components-date-range-style.c017': "/* Error note: written beside the control (the control's `aria-describedby` points at it), **not colour alone**. */",
  'base-render.components-date-range-style.c018': "/* One method sentence: `This week: 09-19 to 09-25, 7 days in total (inclusive)` (**body text to be read**, `ink-2`).",
  'base-render.components-date-range-style.c019': "   The caller's extra sentence hangs at the end, a hairline between the two. */",
