  'base-render.components-drag-sort-style-forms.c001': "/* drag-sort second form (`buttons` button reordering): select a row → the two-half control (up | down) moves it one place,",
  'base-render.components-drag-sort-style-forms.c002': "   the selected row stands up (shadow + accent outline, not colour alone), and a dashed line spanning the row width previews the drop position. */",
  'base-render.components-drag-sort-style-forms.c003': "/* The handle drops to **glyph only**: this row also holds hard buttons like the two-half control, and a soft-filled handle would blur the hierarchy",
  'base-render.components-drag-sort-style-forms.c004': '   (the hit box stays {p0}×{p1}; it is still the "grab" entry). */',
  'base-render.components-drag-sort-style-forms.c005': "/* The selected row **stands up**: shadow (shape, never colour alone) + accent outline; the body does not shift (button reordering keeps the sense of position). */",
  'base-render.components-drag-sort-style-forms.c006': "/* The right-hand reading sits left in this tier (the `margin-left` slack is left for the two-half control at the row end). */",
  'base-render.components-drag-sort-style-forms.c007': "/* Two-half control: **one** unit (one frame, two halves); 8px between the halves — halves that touch get mis-tapped on touchscreens. */",
  'base-render.components-drag-sort-style-forms.c008': '/* The halves: real buttons {p0}×{p1} each, labelled "up" and "down" in words (**no direction arrows**: arrows are not something you can rely on on a phone). */',
  'base-render.components-drag-sort-style-forms.c009': "/* The selected row's control takes the accent tier (frame and text each one step, not just coloured text). */",
  'base-render.components-drag-sort-style-forms.c010': "/* The half that has reached the end cannot be pressed: say so (`disabled`) + one tier weaker text colour, not just slightly lighter text. */",
  'base-render.components-drag-sort-style-forms.c011': "/* Dashed drop preview: the line **spans the row width** (left edge = right edge = row edge), and the label sits on the line saying which position it would land in.",
  'base-render.components-drag-sort-style-forms.c012': '   The dash is one tier lighter than the 3px solid of the "dragging" tier (nothing has moved yet in this tier). */',
  'base-render.components-drag-sort-style-forms.c013': "/* Accessibility floor: a real keyboard user's focus must stay visible (focus is an **enhancement**, not the path — both halves are tappable). */",
  'base-render.components-drag-sort-style-forms.c014': "/* Hover only enhances (and only on devices with a real pointer); tappability does not depend on it. */",
  'base-render.components-drag-sort-style-forms.c015': "/* Narrow tier (**this component's own** < {p0}px): the whole two-half control wraps to the next line, right-aligned,",
  'base-render.components-drag-sort-style-forms.c016': "   no squeezed text, no sideways scroll; the name and position reading wrap as usual, not a single `…`. */",
  /* ── packages/base-render/src/components/drag-sort/style.ts（#1226 迁入） ── */
  'base-render.components-drag-sort-style.c001': '/* drag-sort (drag-to-reorder list · lift form "dragging"):',
  'base-render.components-drag-sort-style.c002': "   card head + row area (handle + index + name + reading) + status sentence + cancel key; the lifted state has all three cues. */",
  'base-render.components-drag-sort-style.c003': "/* Card head: the title + the how-to-grab sentence on the right; once narrow the whole segment wraps to the next line (no squeezed text, no sideways scroll). */",
  'base-render.components-drag-sort-style.c004': "/* Row area: the gap between rows (finger room between adjacent touch targets, 8px). */",
  'base-render.components-drag-sort-style.c005': "/* One row: handle + index + name (takes the leftover width) + right-hand reading + position reading; the whole segment wraps, words are never broken. */",
  'base-render.components-drag-sort-style.c006': "/* Grab handle: a real 44×44 button; `touch-action: none` lets the drag path on touchscreens receive pointermove. */",
  'base-render.components-drag-sort-style.c007': "/* Index: the number for that position (tabular digit slot; **never truncated**). */",
  'base-render.components-drag-sort-style.c008': "/* Name: this row's identity (**wraps, never truncates**). */",
  'base-render.components-drag-sort-style.c009': "/* Lock reason: written in the name cell (semantic-tier text uses `danger`, not the accent colour). */",
  'base-render.components-drag-sort-style.c010': "/* Position reading: every row says which position it is (**never truncated**; the lifted tier takes the accent tier). */",
  'base-render.components-drag-sort-style.c011': "/* The lifted row: it stands up (shifted up 2px + accent outline + 2px primary marker on the left + secondary surface underneath).",
  'base-render.components-drag-sort-style.c012': "   The row's main text stays ink; the 2px marker follows the \"whole row selected\" rule. */",
  'base-render.components-drag-sort-style.c013': "/* The original slot, now empty: dashed frame (shape) + which step is free (word) + accent soft fill and accent text (colour). */",
  'base-render.components-drag-sort-style.c014': "/* The drop bar: a 3px solid line **across the full width** (`i` spans the row, left edge = right edge = row edge; shape) + a capsule on the line at the right (word).",
  'base-render.components-drag-sort-style.c015': "   The label carries its own opaque soft fill and sits on the line: the bar shows on both sides of the label and the right edge is not cut short (same shape as the prototype's `.c-drag-line`). */",
  'base-render.components-drag-sort-style.c016': '/* Status sentence: the real reading of whether it is plain or lifted (`role="status"`, screen readers announce it when the state changes). */',
  'base-render.components-drag-sort-style.c017': "/* Cancel key: only shown in the lifted state (visible and tappable; `hidden` takes it out of reach when nothing is lifted). */",
  'base-render.components-drag-sort-style.c018': "/* A locked row: the handle cannot be pressed, and **it says why** (the reason sits in the name cell). */",
  'base-render.components-drag-sort-style.c019': "/* Accessibility floor: a real keyboard user's focus must stay visible (focus is an **enhancement**, not the path — every row is tappable). */",
  'base-render.components-drag-sort-style.c020': "/* Hover only enhances (and only on devices with a real pointer); tappability does not depend on it. */",
  'base-render.components-drag-sort-style.c021': "/* Reduced motion: the lift tier's translate is switched off outright (nothing stalls midway — state never rides on transitionend). */",
  'base-render.components-drag-sort-style.c022': "/* Second form (`buttons` button reordering, `style-forms.ts`): glyph-only handle / the selected row stands up / two-half control /",
  'base-render.components-drag-sort-style.c023': "   a dashed drop preview spanning the row width. **The whole segment comes after the old tier's rules** — same discipline, same prefix,",
  'base-render.components-drag-sort-style.c024': "   order is cascade order: not one byte or position of the old tier changes. */",
  'base-render.components-drag-sort-style.c025': "/* Narrow tier (**this component's own** < {p0}px): the right-hand reading wraps to the next line, index and name stay put. */",
