  /* ── packages/base-render/src/components/hour-band/style.ts（#1226 迁入） ── */
  'base-render.components-hour-band-style.c001': '/* hour-band (hour band · form A "one band + hour ruler (0–23) + detail rows below"): a day spread into one band,',
  'base-render.components-hour-band-style.c002': '   each segment positioned by "minute of the day", **length is "how long"**; when a segment is wide the duration is written again, with detail rows per segment below.',
  'base-render.components-hour-band-style.c003': "   Hierarchy comes not from shadows or large radii (receipt paper has zero shadow, headline type zero radius): hairlines, weight and depth steps ⇒ reskinning only swaps values. */",
  'base-render.components-hour-band-style.c004': "/* Head: title + purpose + total (the total hugs the right edge; when the container narrows the three wrap on their own, none crushing another). */",
  'base-render.components-hour-band-style.c005': '/* The band: the soft base colour = "this day", a segment = "what is happening" (segments are positioned by percentage and always inside the band). */',
  'base-render.components-hour-band-style.c006': "/* The duration inside a segment: written on a **small card-face chip** (text on depth blocks does not gamble on the scale's lightness, so it stays readable after a reskin).",
  'base-render.components-hour-band-style.c007': "   When the segment is too narrow the word is not shown (decided at normalisation time), and the detail row's reading covers the duration. */",
  'base-render.components-hour-band-style.c008': "/* Hour ruler: **the same 24-column template as the band** (ticks always land on the hour). */",
  'base-render.components-hour-band-style.c009': "/* Legend: swatch + category name (the swatch is aria-hidden, the name is text). */",
  'base-render.components-hour-band-style.c010': "/* Detail row: start-end / name / duration / extra reading. Start-end and duration are `nowrap` (**key readings are never truncated**), the name wraps. */",
  'base-render.components-hour-band-style.c011': '/* The unrecorded row: its name is muted (**"this stretch has no record" is its meaning**). */',
  'base-render.components-hour-band-style.c012': "/* This component carries no clickable elements of its own. This rule is a **floor**: if a caller wraps a row in a link, focus must stay visible —",
  'base-render.components-hour-band-style.c013': "   never `outline:none` without a replacement. */",
  'base-render.components-hour-band-style.c014': "/* Narrow container (<{p0}px): the ruler **keeps only even hours** (one tick every 2 hours).",
  'base-render.components-hour-band-style.c015': '   Twenty-four numbers crowd into a smear in the narrow tier (exactly the "squeezed text" case); every other tick reads clearer.',
  'base-render.components-hour-band-style.c016': "   **`visibility`, not `display:none`**: a `display:none` cell leaves the grid layout,",
  'base-render.components-hour-band-style.c017': "   and the remaining 12 **shift forward** (slot 0 becomes the 1 o'clock position) — the whole ruler would be misaligned (caught by the adjacent-gap judge).",
  'base-render.components-hour-band-style.c018': "   The judge is **this component's own width**: it gets embedded in sidebars, panels and cards, so viewport width ≠ component width. */",
  /* ── packages/base-render/src/components/invoice-lines/model.ts（#1226 迁入） ── */
  'base-render.components-invoice-lines-model.c001': "{p0} less than the original price",
  'base-render.components-invoice-lines-model.c002': "{p0} more than the original price",
  'base-render.components-invoice-lines-model.c003': "Same as the original price",
  'base-render.components-invoice-lines-model.c004': "Discounted to {p0}/10",
  'base-render.components-invoice-lines-model.c005': "{p0} {p1} people, {p2} each",
  'base-render.components-invoice-lines-model.c006': "Not divisible: {p0} each first, the remaining {p1} charged to the payer",
  /* ── packages/base-render/src/components/invoice-lines/style.ts（#1226 迁入） ── */
  'base-render.components-invoice-lines-style.c001': '/* invoice-lines (amount breakdown · form A "line-by-line breakdown + close" / form D "waterfall bars"):',
  'base-render.components-invoice-lines-style.c002': '   every line reads "why", the chain from the original price to the paid amount reads as one chain, the paid amount is bold and enlarged at the end, and the split goes into the secondary line.',
  'base-render.components-invoice-lines-style.c003': "   **Reworked component**: the prototype read like a stack of ordinary ledger rows; with zero shadow and zero radius, indentation, hairlines and a heavy rule do the separating. */",
  'base-render.components-invoice-lines-style.c004': "/* The chain: a hairline between lines; **deductions and additions indent step by step**, so the reader sees at a glance where this amount comes off. */",
  'base-render.components-invoice-lines-style.c005': '/* Deductions and additions: indentation + a left vertical line (**the indent itself** is the shape of "this amount hangs under the line above"). */',
  'base-render.components-invoice-lines-style.c006': "/* Paid: closed by a **heavy rule** (no shadow, no radius), type size doubled — that closing line is the component's reading. */",
  'base-render.components-invoice-lines-style.c007': "/* Amount: tabular digits (aligned up and down one chain); the paid line is bold and enlarged. */",
  'base-render.components-invoice-lines-style.c008': "/* Deductions take the ok tier (money saved); additions take the warn tier (money spent) — **colour is only the second cue**:",
  'base-render.components-invoice-lines-style.c009': '   the sign (−/＋), the indent and the two "why" tags are all there. */',
  'base-render.components-invoice-lines-style.c010': '/* "Why": takes a full row of its own, a tag on the left points out the reason. */',
  'base-render.components-invoice-lines-style.c011': "/* The split note (where the odd cents go when it does not divide evenly): indented + a thinner vertical line, not competing with the body for hierarchy. */",
  'base-render.components-invoice-lines-style.c012': "/* Waterfall bars: segment width is proportional to the amount (width goes into inline style, the ratio computed here). */",
  'base-render.components-invoice-lines-style.c013': "/* Deduction segment: the fill is **computed** from tokens (`ok` mixed into `surface`) — `ok-soft` is near white under both the newspaper and neutral skins,",
  'base-render.components-invoice-lines-style.c014': '   so segment and track bottom would be indistinguishable and "how much was saved" would be invisible in shape. */',
  'base-render.components-invoice-lines-style.c015': "/* The method line under the bar: says what a full-length bar means (**the judge asserts this sentence is present**). */",
  'base-render.components-invoice-lines-style.c016': "/* Legend: amounts that do not fit on the bars are **all listed line by line** here (key meaning is never cut off by segment width).",
  'base-render.components-invoice-lines-style.c017': "   Default (wide tier) two columns; the narrow-tier rule at the end **overrides** it to one. */",
  'base-render.components-invoice-lines-style.c018': "/* Method line: how this amount was split (one span per segment, a hairline between segments). */",
  'base-render.components-invoice-lines-style.c019': "/* Focus floor: this component has no clickable elements of its own; if a caller wraps a line in a link, focus must stay visible. */",
  'base-render.components-invoice-lines-style.c020': "/* Narrow container (≤{p0}px): the legend's two columns are **overridden** to one",
  'base-render.components-invoice-lines-style.c021': "   (the judge is this component's own width, not the viewport width). */",
  'base-render.components-invoice-lines-style.c022': "/* Segment-width floor constant (the judge reads it from source): segments narrower than {p0}% carry no text, their amounts are listed line by line in the legend instead. */",
  /* ── packages/base-render/src/components/kanban-columns/attrs.ts（#1226 迁入） ── */
