  /* ── packages/base-render/src/components/kanban-columns/style-grouped.ts（#1226 迁入） ── */
  'base-render.components-kanban-columns-style-grouped.c001': '/* kanban-columns (grouped form "columns by position + a second grouping level inside"): a column = a position, with one more group level inside.',
  'base-render.components-kanban-columns-style-grouped.c002': "   This tier has no drop line and no empty-slot narration — a header reading line, a group-name reading line, and an item-row reading line. */",
  'base-render.components-kanban-columns-style-grouped.c003': "/* Column shell: in this tier a column is a **standing board** (`--shadow` is a real shadow under the neutral skin; paper skins are none by design). */",
  'base-render.components-kanban-columns-style-grouped.c004': '/* Column head: **one reading line says it all** — "column name + count" share a line (the three areas of the `status` tier collapse into one here). */',
  'base-render.components-kanban-columns-style-grouped.c005': "/* Column body: 12px between groups (one tier wider than the 8px between item rows — hierarchy comes from whitespace first, then from those two lines). */",
  'base-render.components-kanban-columns-style-grouped.c006': "/* Second level: a {p0}px vertical edge + left indent.",
  'base-render.components-kanban-columns-style-grouped.c007': "   **The only hierarchy edge in this tier**: the item rows inside a group carry no edge of their own (the prototype showed six edges along the left edge being read). */",
  'base-render.components-kanban-columns-style-grouped.c008': "/* Group name row: one reading each for the group name and its count; **a hairline underneath** separates the group-name layer from the item-row layer. */",
  'base-render.components-kanban-columns-style-grouped.c009': "/* One item row: **the whole row is the button** (name + amount on one line, hit box = the whole row).",
  'base-render.components-kanban-columns-style-grouped.c010': "   That 2px is a **transparent slot**: nothing is drawn when not lifted, it becomes the primary side marker when lifted, and no glyph in the row shifts a pixel. */",
  'base-render.components-kanban-columns-style-grouped.c011': "/* The lifted row = the **whole-row selected** tier: soft fill (secondary surface) + a 2px primary side marker on the left + the row's main text still `ink`;",
