  /* ── packages/base-render/src/components/note-block/style.ts（#1226 迁入） ── */
  'base-render.components-note-block-style.c001': '/* note-block (note block · form A "vertical-line note"): hierarchy = vertical line + indent + fill block.',
  'base-render.components-note-block-style.c002': "   **Reworked component**: the quotation form (a short rule + one italic sentence) scored 2 across all three skins and was cut;",
